package org.zhixiaoce.aperture;
import android.app.Activity;import android.os.Bundle;import android.graphics.*;import android.media.ExifInterface;import java.io.*;import java.net.*;import java.util.*;import org.json.*;
/** Isolated emulator checks for the real Android codec, private store and LAN upload transport. */
public final class GalleryProbe extends Activity {
    int passed;GalleryUpload server;void check(boolean value,String name)throws Exception{if(!value)throw new Exception(name);passed++;}
    public void onCreate(Bundle b){super.onCreate(b);new Thread(()->{JSONObject report=new JSONObject();try{runChecks();report.put("passed",passed).put("ok",true);}catch(Throwable e){try{report.put("ok",false).put("passed",passed).put("error",e.toString());}catch(Exception ignored){}}finally{if(server!=null)server.close();}try(FileOutputStream out=openFileOutput("result.json",0)){out.write(report.toString().getBytes("UTF-8"));}catch(Exception ignored){}android.util.Log.i("KaishiGalleryProbe",report.toString());},"Gallery-probe").start();}
    void runChecks()throws Exception{
        File dir=new File(getFilesDir(),"local-gallery");remove(dir);GalleryStore store=new GalleryStore(this);check(store.snapshot().getJSONArray("photos").length()==0,"empty initial album");
        Bitmap b=Bitmap.createBitmap(80,40,Bitmap.Config.ARGB_8888);b.eraseColor(Color.RED);File input=new File(getCacheDir(),"input.jpg");try(FileOutputStream out=new FileOutputStream(input)){b.compress(Bitmap.CompressFormat.JPEG,90,out);}b.recycle();ExifInterface exif=new ExifInterface(input.getAbsolutePath());exif.setAttribute(ExifInterface.TAG_ORIENTATION,"6");exif.setAttribute(ExifInterface.TAG_GPS_LATITUDE,"31/1,0/1,0/1");exif.saveAttributes();byte[] image=bytes(new FileInputStream(input));
        String id=store.add(image,()->true);check(GalleryStore.id(id),"opaque safe id");File photo=new File(dir,id+".jpg");BitmapFactory.Options bounds=new BitmapFactory.Options();bounds.inJustDecodeBounds=true;BitmapFactory.decodeFile(photo.getAbsolutePath(),bounds);check(bounds.outWidth==40&&bounds.outHeight==80,"EXIF orientation normalized");check(new ExifInterface(photo.getAbsolutePath()).getAttribute(ExifInterface.TAG_GPS_LATITUDE)==null,"GPS removed");check(new File(new File(dir,"thumbs"),id+".jpg").isFile(),"thumbnail saved");check(new GalleryStore(this).snapshot().getJSONArray("photos").length()==1,"photos persist across store instances");
        store.option("template","diptych");store.option("seconds","20");check(new GalleryStore(this).snapshot().getString("template").equals("diptych")&&store.snapshot().getInt("seconds")==20,"template persistence");
        reject(()->store.add(image,()->false),"closed session cannot commit");reject(()->store.add(new byte[32],()->true),"malformed image rejected");reject(()->store.delete("../input"),"path traversal rejected");
        server=new GalleryUpload(this,()->{});String link=server.start();URI uri=URI.create(link);String token=uri.getFragment();check(token.length()==32&&uri.getQuery()==null,"QR secret in fragment only");
        String unauthorized=request(uri,"POST /upload HTTP/1.1\r\nHost: "+uri.getAuthority()+"\r\nContent-Length: 1\r\n\r\n",new byte[]{1});check(unauthorized.startsWith("HTTP/1.1 403"),"upload requires scan capability");
        String result=request(uri,"POST /upload HTTP/1.1\r\nHost: "+uri.getAuthority()+"\r\nOrigin: http://"+uri.getAuthority()+"\r\nAuthorization: Bearer "+token+"\r\nContent-Type: image/jpeg\r\nContent-Length: "+image.length+"\r\n\r\n",image);check(result.startsWith("HTTP/1.1 200")&&result.contains("\"saved\":true"),"actual socket upload saved");check(store.snapshot().getJSONArray("photos").length()==2,"uploaded photo visible to gallery");
        String bad;try{bad=request(uri,"POST /upload HTTP/1.1\r\nHost: "+uri.getAuthority()+"\r\nOrigin: https://evil.invalid\r\nAuthorization: Bearer "+token+"\r\nContent-Length: "+image.length+"\r\n\r\n",image);}catch(IOException expected){bad="";}check(!bad.startsWith("HTTP/1.1 200"),"foreign origin rejected");
        String page=request(uri,"GET / HTTP/1.1\r\nHost: "+uri.getAuthority()+"\r\n\r\n",new byte[0]);check(page.startsWith("HTTP/1.1 200")&&page.contains("上传到电视相册"),"phone upload page served offline");
        GalleryUpload alreadyClosed=new GalleryUpload(this,()->{});alreadyClosed.close();reject(alreadyClosed::start,"closed upload cannot restart");
        server.close();reject(()->request(uri,"GET / HTTP/1.1\r\nHost: "+uri.getAuthority()+"\r\n\r\n",new byte[0]),"closing session revokes listener");store.delete(id);check(!photo.exists()&&!new File(new File(dir,"thumbs"),id+".jpg").exists(),"delete removes photo and thumbnail");
        remove(dir);dir.mkdirs();File sparse=new File(dir,"00000000000000000000000000000000.jpg");try(RandomAccessFile out=new RandomAccessFile(sparse,"rw")){out.setLength(GalleryStore.MAX_BYTES);}reject(()->store.add(image,()->true),"quota enforced before write");remove(dir);
    }
    interface Run{void run()throws Exception;}void reject(Run action,String name)throws Exception{try{action.run();}catch(Exception expected){passed++;return;}throw new Exception(name);}
    static byte[] bytes(InputStream in)throws Exception{try(InputStream stream=in;ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=stream.read(b))!=-1)out.write(b,0,n);return out.toByteArray();}}
    String request(URI u,String head,byte[] body)throws Exception{try(Socket s=new Socket()){s.connect(new InetSocketAddress(u.getHost(),u.getPort()),2000);s.setSoTimeout(5000);s.getOutputStream().write(head.getBytes("US-ASCII"));s.getOutputStream().write(body);s.getOutputStream().flush();ByteArrayOutputStream response=new ByteArrayOutputStream();try{byte[] buffer=new byte[4096];int n;while((n=s.getInputStream().read(buffer))!=-1)response.write(buffer,0,n);}catch(SocketException reset){if(response.size()==0)throw reset;}return new String(response.toByteArray(),"UTF-8");}}
    void remove(File f){if(f.isDirectory())for(File child:f.listFiles())remove(child);f.delete();}
}
